body {
  margin: 0;
  background: #f5f7fb;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 14px;
  box-sizing: border-box;
}

.top {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  background: #101828;
  color: white;
  border-radius: 8px;
  padding: 14px;
}

.top span {
  color: #98a2b3;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.top h1 {
  margin: 4px 0;
  font-size: 24px;
}

.top p {
  margin: 0;
  color: #d0d5dd;
  font-size: 12px;
}

.actions {
  display: flex;
  gap: 8px;
}

button {
  height: 34px;
  border: 1px solid #d0d5dd;
  border-radius: 7px;
  background: white;
  color: #101828;
  font-weight: 800;
  padding: 0 12px;
  cursor: pointer;
}

button.primary {
  background: #0f766e;
  border-color: #0f766e;
  color: white;
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin: 12px 0;
}

.kpis div {
  background: white;
  border: 1px solid #d0d5dd;
  border-left: 4px solid #0f766e;
  border-radius: 8px;
  padding: 10px;
}

.kpis span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 900;
}

.kpis b {
  display: block;
  margin-top: 5px;
  font-size: 20px;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: white;
  border: 1px solid #d0d5dd;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 8px;
  font-size: 12px;
  border-bottom: 1px solid #eaecf0;
  vertical-align: top;
}

tr.done {
  background: #f0fdf4;
}

td b {
  display: block;
}

td small {
  display: block;
  color: #667085;
  margin-top: 2px;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.pill {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.pill.ok {
  background: #dcfce7;
  color: #166534;
}

.pill.open {
  background: #fff7ed;
  color: #c2410c;
}

.empty {
  margin-top: 12px;
  background: white;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 20px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .actions,
  .no-print {
    display: none;
  }
  .top,
  .kpis div,
  table {
    box-shadow: none;
  }
}

