import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function pick(row, keys, fallback = "") {
  for (const key of keys) {
    if (row && row[key] !== undefined && row[key] !== null && row[key] !== "") return row[key];
  }
  return fallback;
}

function done(row) {
  const status = String(pick(row, ["status", "Status"], "")).toUpperCase();
  return ["DONE", "COMPLETED", "PICKED"].includes(status);
}

function App() {
  const model = appsmith.model || {};
  const rows = model.rows || [];
  const summary = model.summary || {};

  const trigger = (action, row = {}) => {
    appsmith.updateModel({ action, row });
    appsmith.triggerEvent("onReplenishmentAction");
  };

  return (
    <div className="page">
      <div className="top">
        <div>
          <span>Inventory Operations</span>
          <h1>Replenishment Report</h1>
          <p>Printed: {model.printedAt || "-"} {model.printedBy ? `by ${model.printedBy}` : ""}</p>
        </div>

        <div className="actions">
          <button onClick={() => trigger("refresh")}>Refresh</button>
          <button className="primary" onClick={() => window.print()}>Print</button>
        </div>
      </div>

      <div className="kpis">
        <div><span>Lines</span><b>{summary.lines || 0}</b></div>
        <div><span>Open</span><b>{summary.openLines || 0}</b></div>
        <div><span>Picked</span><b>{summary.pickedLines || 0}</b></div>
        <div><span>Total Qty</span><b>{qty(summary.totalQty)}</b></div>
      </div>

      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Task</th>
            <th>Product</th>
            <th>From</th>
            <th>To</th>
            <th className="right">Qty</th>
            <th>Note</th>
            <th className="no-print">Action</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row, index) => {
            const isDone = done(row);

            return (
              <tr key={index} className={isDone ? "done" : ""}>
                <td>
                  <span className={`pill ${isDone ? "ok" : "open"}`}>
                    {isDone ? "Picked" : "Open"}
                  </span>
                </td>
                <td>
                  <b>{pick(row, ["taskNumber", "task_number", "Task Number"], `#${index + 1}`)}</b>
                  <small>{pick(row, ["taskType", "task_type", "Task Type"], "")}</small>
                </td>
                <td>
                  <b>{pick(row, ["productCode", "Product Code", "code"], "")}</b>
                  <small>{pick(row, ["productName", "Product Name", "name"], "")}</small>
                </td>
                <td>{pick(row, ["sourceLocation", "sourceLocationCode", "fromLocation", "From"], "-")}</td>
                <td>{pick(row, ["destinationLocation", "destinationLocationCode", "toLocation", "To"], "-")}</td>
                <td className="right">{qty(pick(row, ["quantity", "requiredQuantity", "Required Qty"], 0))}</td>
                <td>{pick(row, ["note", "Note"], "")}</td>
                <td className="no-print">
                  <button disabled={isDone} onClick={() => trigger("markPicked", row)}>
                    {isDone ? "Done" : "Mark Picked"}
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      {!rows.length && <div className="empty">No replenishment lines found.</div>}
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
